import {controller} from '@github/catalyst'
import {sendEvent} from '@github-ui/hydro-analytics'
import {distance} from 'fastest-levenshtein'
import {
  COPILOT_HINT_TEXT_ATTR,
  COPILOT_HINT_ANCHOR_ATTR,
  COPILOT_HINT_ID_ATTR,
} from '@github-ui/copilot-apply-changes-button/CopilotApplyChangesButton'
import {AT_COPILOT_VALUE} from '@github-ui/filter/providers'

/**
 * Checks if the comment body mentions @copilot
 * Matches: @copilot, @Copilot, or any case variation when followed by whitespace or punctuation
 */
function mentionsCopilot(commentBody: string): boolean {
  // Match @copilot at start of string or after whitespace, followed by non-word character or end of string
  // Use AT_COPILOT_VALUE constant to ensure consistency across the codebase
  const mentionPattern = new RegExp(`(^|[\\s])${AT_COPILOT_VALUE}([^\\w]|$)`, 'i')
  return mentionPattern.test(commentBody)
}

/**
 * Normalizes strings by trimming and collapsing whitespace, then uses
 * fastest-levenshtein to compute edit distance.
 * Returns a value between 0 (completely different) and 1 (identical).
 */
function computeSimilarity(str1: string, str2: string): number {
  // Handle edge cases
  if (str1 === str2) return 1.0
  if (str1.length === 0 || str2.length === 0) return 0.0

  // Normalize strings: trim and normalize whitespace
  const normalized1 = str1.trim().replace(/\s+/g, ' ')
  const normalized2 = str2.trim().replace(/\s+/g, ' ')

  if (normalized1 === normalized2) return 1.0

  // Compute Levenshtein distance using fastest-levenshtein
  const editDistance = distance(normalized1, normalized2)
  const maxLength = Math.max(normalized1.length, normalized2.length)

  // Normalize to 0-1 range (1 = identical, 0 = completely different)
  return 1 - editDistance / maxLength
}

/**
 * Catalyst controller that sends telemetry when a pull request comment
 * mentioning @copilot is submitted. This is a remote behavior that listens
 * for form submissions within its container.
 *
 * Usage:
 *   <copilot-comment-mention-telemetry-element>
 *     <form class="js-new-comment-form">...</form>
 *   </copilot-comment-mention-telemetry-element>
 */
@controller
export class CopilotCommentMentionTelemetryElement extends HTMLElement {
  connectedCallback() {
    // Listen for submit events on comment forms within this element
    this.addEventListener('submit', this.#handleSubmit)
  }

  disconnectedCallback() {
    this.removeEventListener('submit', this.#handleSubmit)
  }

  #handleSubmit = (event: Event) => {
    const target = event.target
    if (!(target instanceof HTMLFormElement)) return

    // Only process comment forms (both inline and overview comments)
    const isCommentForm =
      target.classList.contains('js-inline-comment-form') || target.classList.contains('js-new-comment-form')

    if (!isCommentForm) return

    // Find the comment textarea
    const commentField = target.querySelector<HTMLTextAreaElement>('.js-comment-field')
    if (!commentField) return

    const commentBody = commentField.value.trim()
    if (!commentBody) return

    // Check if comment mentions @copilot
    if (!mentionsCopilot(commentBody)) return

    // Only send telemetry if all stored fields are present (indicating this came from the button)
    const hintText = commentField.getAttribute(COPILOT_HINT_TEXT_ATTR)
    const storedAnchor = commentField.getAttribute(COPILOT_HINT_ANCHOR_ATTR)
    const hintId = commentField.getAttribute(COPILOT_HINT_ID_ATTR)

    if (!hintText || !storedAnchor || !hintId) return

    // Compute hint similarity using the stored hint text
    const hintSimilarity = computeSimilarity(hintText, commentBody)

    // Clean up the stored attributes
    commentField.removeAttribute(COPILOT_HINT_TEXT_ATTR)
    commentField.removeAttribute(COPILOT_HINT_ANCHOR_ATTR)
    commentField.removeAttribute(COPILOT_HINT_ID_ATTR)

    // Send telemetry event using the stored anchor and hint ID from the button click
    sendEvent('cca_comment_mention_submitted', {
      commentAnchor: storedAnchor,
      hintSimilarity,
      hintId,
    })
  }
}
